<template>
  <section class="qa-corpus" data-testid="qa-corpus-panel" :aria-busy="loading">
    <header><h1>{{ $t('qaCorpus.title') }}</h1><p>{{ $t('qaCorpus.intro') }}</p></header>
    <details class="qa-corpus-scope"><summary>{{ $t('qaCorpus.scopeTitle') }}</summary><p>{{ $t('qaCorpus.scope') }}</p><p>{{ $t('qaCorpus.smokeLimit') }}</p></details>
    <p v-if="error" class="qa-state qa-error" role="alert" data-testid="qa-corpus-error">{{ $t('qaCorpus.errors.' + error) }} <button class="qa-text-link" :disabled="loading" @click="load">{{ $t('qaLive.refresh') }}</button></p>
    <section v-if="bank" class="qa-panel qa-corpus-bank" data-testid="qa-corpus-bank">
      <h2>{{ $t('qaCorpus.bankTitle') }}</h2><p><strong>{{ bank.id }}</strong> · {{ bank.version }} · {{ $t('qaCorpus.bankCount', { cases: bank.case_count, documents: bank.document_count }) }}</p>
      <dl class="qa-corpus-meta"><div><dt>{{ $t('qaCorpus.bankHash') }}</dt><dd><code>{{ bank.sha256 }}</code></dd></div><div><dt>{{ $t('qaCorpus.sourceHash') }}</dt><dd><code>{{ bank.source_sha256 }}</code></dd></div><div><dt>{{ $t('qaCorpus.newsWindow') }}</dt><dd>{{ bank.coverage.date_window.start }} — {{ bank.coverage.date_window.end }}</dd></div><div><dt>{{ $t('qaCorpus.captured') }}</dt><dd>{{ timestamp(bank.provenance.captured_at) }}</dd></div></dl>
      <div class="qa-corpus-coverage">
        <div v-for="kind in coverageKinds" :key="kind" :data-testid="'qa-corpus-coverage-' + kind"><h3>{{ $t('qaCorpus.coverage.' + kind) }}</h3><p>{{ describeCoverage(bank.coverage[kind], kind) }}</p></div>
        <details class="qa-corpus-task-types" data-testid="qa-corpus-task-types"><summary>{{ $t('qaCorpus.taskTypeSummary', { types: Object.keys(bank.coverage.task_types).length, cases: bank.case_count }) }}</summary><p>{{ describeCoverage(bank.coverage.task_types, 'task_types') }}</p></details>
      </div>
      <details><summary>{{ $t('qaCorpus.provenance') }}</summary><p><code>{{ bank.provenance.alias }}</code> · {{ bank.provenance.embed_model }} · {{ bank.provenance.embed_dim }} D</p><p v-for="index in bank.provenance.indices" :key="index.name"><code>{{ index.name }}</code> · {{ index.uuid }}</p><p>{{ $t('qaCorpus.mapping') }} <code>{{ bank.provenance.mapping_sha256 }}</code></p></details>
      <p>{{ $t('qaCorpus.fixedVsLive') }}</p>
    </section>
    <section v-if="settings && !harness" class="qa-panel qa-corpus-settings">
      <h2>{{ $t('qaCorpus.configure') }}</h2>
      <p v-if="!capabilities?.available" data-testid="qa-corpus-unavailable">{{ unavailable }}</p>
      <template v-if="capabilities?.pricing"><p>{{ $t('qaCorpus.model', { model: capabilities.pricing.model, embedding: capabilities.pricing.embedding_model }) }}</p><p>{{ $t('qaCorpus.reserve', { reserve: money(capabilities.pricing.reserved_estimated_usd), ceiling: money(capabilities.limits.max_budget_usd) }) }}</p><details><summary>{{ $t('qaFlowValidation.pricingDetails') }}</summary><p v-for="kind in ['main', 'judge', 'embedding']" :key="kind">{{ $t('qaValidation.pricing.' + kind) }} · {{ $t('qaValidation.rate', { input: money(capabilities.pricing[kind].input_per_million), output: kind === 'embedding' ? '—' : money(capabilities.pricing[kind].output_per_million) }) }}</p><p>{{ $t('qaCorpus.judgeLimit') }}</p></details></template>
      <label class="qa-corpus-budget">{{ $t('qaCorpus.split') }}<select v-model="split" data-testid="qa-corpus-split" :disabled="loading || active"><option value="all">{{ $t('qaCorpus.splits.all') }}</option><option v-for="value in ['dev', 'holdout']" :key="value" :value="value" :disabled="!capabilities?.bank?.coverage?.splits?.[value]">{{ $t('qaCorpus.splits.' + value) }}</option></select></label>
      <label class="qa-corpus-budget">{{ $t('qaLive.budget') }}<input v-model.number="budget" data-testid="qa-corpus-budget" type="number" :min="capabilities?.pricing?.per_case_reserved_estimated_usd || 0.01" :max="capabilities?.limits?.max_budget_usd || 50" step="0.01" :disabled="loading || active" /></label>
      <label class="qa-corpus-ack"><input v-model="acknowledged" data-testid="qa-corpus-ack" type="checkbox" :disabled="loading || active" /><span>{{ $t('qaCorpus.consent') }}</span></label>
      <div v-if="capabilities?.turnstile_required"><p>{{ $t(tsSitekey ? 'qaValidation.turnstile' : 'qaValidation.turnstileUnavailable') }}</p><div ref="tsBox"></div></div>
      <button class="qa-button qa-primary" data-testid="qa-corpus-start" :disabled="cannotStart" @click="start"><QaIcon name="play_arrow" />{{ $t('qaCorpus.start') }}</button>
      <p v-if="!job" data-testid="qa-corpus-not-run"><strong>{{ $t('qaCorpus.notRun') }}</strong> · {{ $t('qaCorpus.notEvidence') }}</p>
    </section>
    <section v-if="job" class="qa-panel qa-corpus-evidence" data-testid="qa-corpus-evidence">
      <div class="qa-corpus-heading"><h2>{{ $t('qaCorpus.result') }}</h2><button v-if="!active && !harness" class="qa-button" type="button" @click="prepareRun">{{ $t('qaCorpus.configure') }}</button></div>
      <p><strong data-testid="qa-corpus-status">{{ $t('qaCorpus.status.' + job.status) }}</strong> · {{ job.id }} · {{ splitLabel(job.split) }} · {{ job.model || job.pricing?.model }} · <code>{{ job.source_sha }}</code></p>
      <section v-if="harness" class="qa-state qa-corpus-harness" data-testid="qa-corpus-harness-scope"><h3>{{ $t('qaCorpus.harness.title') }}</h3><p>{{ $t('qaCorpus.harness.readOnly') }}</p><p>{{ $t('qaCorpus.harness.scope') }}</p><p v-if="combinedBudget?.version === 2" data-testid="qa-corpus-rerun-limit">{{ $t('qaCorpus.harness.rerunLimit') }}</p><p>{{ $t('qaCorpus.harness.excluded') }}</p><details><summary>{{ $t('qaCorpus.harness.sourceRevision') }}</summary><p>{{ $t('qaCorpus.harness.sourceFiles') }} <code>{{ job.source_files_sha256 }}</code></p><p>{{ $t('qaCorpus.harness.durability') }}</p></details></section>
      <p>{{ $t('qaCorpus.executionBank') }} {{ job.bank.id }} · {{ job.bank.version }}<br /><code>{{ job.bank.sha256 }}</code></p><p v-if="capabilities?.bank && capabilities.bank.sha256 !== job.bank.sha256" class="qa-state">{{ $t('qaCorpus.otherBank') }}</p>
      <p>{{ $t(harness ? 'qaCorpus.harness.attempted' : 'qaCorpus.executed', { done: job.completed_cases, total: job.total_cases, unexecuted: job.total_cases - job.completed_cases }) }}</p><p v-if="harness" data-testid="qa-corpus-harness-coverage">{{ $t('qaCorpus.harness.completedAnswers', { n: completedAnswers }) }} · {{ $t('qaCorpus.harness.assessedCoverage', { n: review ? review.passed + review.failed : 0, total: job.total_cases }) }}</p><p>{{ $t('qaCorpus.selectedScope', { selected: job.total_cases, bank: job.bank.case_count, unselected: job.bank.case_count - job.total_cases }) }}</p><p>{{ $t('qaCorpus.executedAt') }} {{ timestamp(job.started_at) }}<span v-if="job.finished_at"> — {{ timestamp(job.finished_at) }}</span></p>
      <p v-if="job.error" class="qa-state qa-error">{{ job.error }}</p>
      <p v-if="job.archive_error" class="qa-state qa-error">{{ $t('qaCorpus.errors.storage') }} · {{ job.archive_error }}</p>
      <section v-if="ledger" class="qa-corpus-harness-ledger" data-testid="qa-corpus-harness-ledger">
        <h3>{{ $t('qaCorpus.harness.costTitle') }}</h3>
        <section v-if="costObservation" data-testid="qa-corpus-standard-cost"><h4>{{ $t('qaCorpus.harness.costObservation.title') }}</h4><dl class="qa-corpus-meta"><div v-for="field in ['current', 'prior', 'total']" :key="field"><dt>{{ $t('qaCorpus.harness.costObservation.' + (costObservation.version === 2 && field !== 'current' ? field + 'All' : field)) }}</dt><dd>US$ {{ standardMoney(costObservation[field]) }}</dd></div></dl><p>{{ $t('qaCorpus.harness.costObservation.' + (costObservation.version === 2 ? 'noteAll' : 'note')) }}</p><details><summary>{{ $t('qaCorpus.harness.costObservation.provenance') }}</summary><p>{{ $t('qaCorpus.harness.costObservation.report') }} <code>{{ costObservation.reportHash }}</code></p><template v-if="costObservation.version === 2"><div v-for="prior in costObservation.priorObservations" :key="prior.runId" data-testid="qa-corpus-prior-cost-observation"><p><code>{{ prior.runId }}</code> · {{ $t('qaCorpus.harness.costObservation.kinds.' + prior.kind) }} · US$ {{ standardMoney(prior.amount) }}</p><p>{{ $t('qaCorpus.harness.combined.priorReport') }} <code>{{ prior.reportHash }}</code></p><p>{{ $t('qaCorpus.harness.costObservation.evidence') }} <code>{{ prior.evidenceHash }}</code></p></div></template><p v-else>{{ $t('qaCorpus.harness.costObservation.diagnosis') }} <code>{{ costObservation.diagnosisHash }}</code></p></details></section>
        <section v-if="combinedBudget" data-testid="qa-corpus-combined-budget"><h4>{{ $t('qaCorpus.harness.combined.title') }}</h4><dl class="qa-corpus-meta"><div v-for="field in combinedFields" :key="field"><dt>{{ $t('qaCorpus.harness.combined.' + field) }}</dt><dd>US$ {{ ledgerMoney(combinedBudget[field]) }}</dd></div></dl><p>{{ $t('qaCorpus.harness.combined.' + (combinedBudget.version === 2 ? 'policyAll' : 'policy')) }}</p><details><summary>{{ $t('qaCorpus.harness.combined.provenance') }}</summary><template v-if="combinedBudget.version === 2"><div v-for="prior in combinedBudget.priorRuns" :key="prior.runId" data-testid="qa-corpus-prior-budget"><p>{{ $t('qaCorpus.harness.combined.priorRun') }} <code>{{ prior.runId }}</code></p><p>{{ $t('qaCorpus.harness.combined.priorCommitted') }} US$ {{ ledgerMoney(prior.committed) }} · {{ $t('qaCorpus.harness.combined.priorUnknown') }} US$ {{ ledgerMoney(prior.unknown) }}</p><p>{{ $t('qaCorpus.harness.combined.priorReport') }} <code>{{ prior.reportHash }}</code></p><p>{{ $t('qaCorpus.harness.combined.priorCheckpoint') }} <code>{{ prior.checkpointHash }}</code></p></div></template><template v-else><p>{{ $t('qaCorpus.harness.combined.priorRun') }} <code>{{ combinedBudget.priorRunId }}</code></p><p>{{ $t('qaCorpus.harness.combined.priorReport') }} <code>{{ combinedBudget.priorReport }}</code></p><p>{{ $t('qaCorpus.harness.combined.priorCheckpoint') }} <code>{{ combinedBudget.priorCheckpoint }}</code></p></template></details></section>
        <dl class="qa-corpus-meta"><div v-for="field in ledgerFields" :key="field.key"><dt>{{ $t(combinedBudget && field.value === 'cap' ? 'qaCorpus.harness.combined.runCap' : 'qaCorpus.harness.' + field.key) }}</dt><dd>US$ {{ ledgerMoney(ledger[field.value]) }}</dd></div><div><dt>{{ $t('qaCorpus.harness.costRequests') }}</dt><dd>{{ ledger.requests }}</dd></div></dl><p>{{ $t('qaCorpus.harness.costLimit') }}</p><details><summary>{{ $t('qaCorpus.harness.costDetails') }}</summary><pre>{{ formatted(job.provider_budget) }}</pre></details>
      </section>
      <button v-if="active" class="qa-button" data-testid="qa-corpus-cancel" :disabled="loading || cancelling" @click="cancel">{{ $t('qaLive.cancel') }}</button>
      <dl class="qa-corpus-metrics"><div><dt>{{ $t('qaCorpus.retrieval') }}</dt><dd>{{ noRetrieval ? $t('qaCorpus.harness.noRetrievalSummary') : $t('qaCorpus.resultCounts', { passed: job.retrieval.passed, failed: job.retrieval.failed }) }}</dd></div><div><dt>{{ $t('qaCorpus.semantic') }}</dt><dd data-testid="qa-corpus-semantic">{{ reviewLabel }}</dd><dd v-if="review"><span v-if="!harness || review.passed + review.failed > 0">{{ $t('qaCorpus.resultCounts', { passed: review.passed, failed: review.failed }) }} · </span>{{ review.reviewer }} · {{ timestamp(review.reviewed_at) }}</dd></div></dl>
      <p v-if="harness && job.cases.length && job.cases.every((row) => !row.retrieval.calls.length)" data-testid="qa-corpus-no-retrieval">{{ $t('qaCorpus.harness.noRetrieval') }}</p><p>{{ $t('qaCorpus.metricScope') }}</p><p>{{ $t('qaCorpus.qualityLimit') }}</p>
      <div class="qa-corpus-actions"><button class="qa-button" :disabled="!job.report_available || downloading" data-testid="qa-corpus-report" @click="download('report')"><QaIcon name="download" />{{ $t('qaLive.download') }}</button><button v-if="review" class="qa-button" :disabled="downloading" @click="download('review')">{{ $t('qaSemanticReview.download') }}</button><label v-if="!harness" class="qa-button qa-corpus-file" :aria-disabled="!canReview">{{ $t('qaSemanticReview.import') }}<input data-testid="qa-corpus-review-file" type="file" accept="application/json,.json" :disabled="!canReview" @change="importReview" /></label></div>
      <p v-if="!harness">{{ $t('qaCorpus.reviewImportHint') }}</p><a v-if="downloadLink" :href="downloadLink.url" :download="downloadLink.filename">{{ $t('qaLive.download') }}</a>
      <details v-if="harness && notRunCaseIds.length" data-testid="qa-corpus-not-run-cases"><summary>{{ $t('qaCorpus.harness.notRunCases', { n: notRunCaseIds.length }) }}</summary><ul><li v-for="caseId in notRunCaseIds" :key="caseId"><code>{{ caseId }}</code> · {{ $t('qaCorpus.harness.notRunCase') }}</li></ul></details>
      <details v-for="row in job.cases" :key="row.case_id" class="qa-corpus-case" data-testid="qa-corpus-case">
        <summary><strong>{{ row.case_id }}</strong> · {{ splitLabel(row.split) }} · {{ row.category }} · {{ taskTypeLabel(row.task_type) }} <span>{{ $t('qaCorpus.retrieval') }} {{ harness && !row.retrieval.calls.length ? $t('qaCorpus.harness.noRetrievalShort') : row.retrieval.passed ? 'PASS' : 'FAIL' }}</span><span v-if="caseReview(row)">{{ $t('qaCorpus.semantic') }} {{ caseReview(row).assessment_status === 'not_assessable' ? $t('qaCorpus.harness.notAssessable') : corpusCasePassed(caseReview(row)) ? 'PASS' : 'FAIL' }}</span></summary>
        <ol><li v-for="(question, index) in row.questions" :key="index">{{ question }}</li></ol>
        <h3>{{ $t('qaCorpus.expectedFacts') }}</h3><ul><li v-for="(fact, index) in row.expected_facts" :key="index"><strong>{{ fact.claim }}</strong><blockquote>{{ fact.quote }}</blockquote><code>{{ fact.article_id }}</code></li></ul>
        <h3>{{ $t('qaCorpus.expectedSources') }}</h3><ul><li v-for="source in row.expected_sources" :key="source.article_id"><a v-if="safeUrl(source.source?.url)" :href="source.source.url" target="_blank" rel="noopener noreferrer">{{ source.title }}</a><span v-else>{{ source.title }}</span> · {{ source.posted_at }} · {{ source.source?.site }} <code>{{ source.article_id }}</code><small>{{ source.content_sha256 }}</small></li></ul>
        <h3>{{ $t('qaCorpus.observedAnswers') }}</h3><p v-if="!row.answers.length">{{ $t('qaCorpus.noAnswer') }}</p><section v-for="answer in row.answers" :key="answer.turn" class="qa-corpus-answer">
          <h4>{{ $t('qaCorpus.turn', { n: answer.turn }) }} · {{ answer.question }}</h4><p class="qa-corpus-answer-text">{{ answer.answer_md || $t('qaCorpus.noAnswer') }}</p>
          <div v-if="harness" data-testid="qa-corpus-answer-citations"><p><strong>{{ $t('qaCorpus.harness.actualCitations') }}</strong></p><ul v-if="answer.citations.length"><li v-for="(citation, index) in answer.citations" :key="citation.id ?? index" :data-citation-ref="citation.id">[{{ citation.id }}] <a v-if="safeUrl(citation.url)" :href="citation.url" target="_blank" rel="noopener noreferrer">{{ citation.title || citation.url }}</a><span v-else>{{ citation.title || citation.url }}</span></li></ul><p v-else>{{ $t('qaCorpus.harness.noCitations') }}</p></div>
          <details><summary>{{ $t(harness ? 'qaCorpus.harness.answerEvidence' : 'qaCorpus.answerEvidence') }}</summary><p>{{ $t(harness ? 'qaCorpus.harness.referenceLimit' : 'qaCorpus.referenceLimit') }}</p><pre>{{ formatted(corpusAnswerEvidence(row, answer)) }}</pre></details>
        </section>
        <p v-if="harness && missingTurns(row).length" data-testid="qa-corpus-missing-turns">{{ $t('qaCorpus.harness.missingTurns', { turns: missingTurns(row).join(', ') }) }}</p>
        <details><summary>{{ $t('qaCorpus.actualToolTrace') }}</summary><p>{{ $t('qaCorpus.groundingScope') }}</p><p v-if="row.tool_trace_truncated || !row.tool_trace?.length" class="qa-error">{{ $t('qaCorpus.traceIncomplete') }}</p><pre>{{ formatted(row.tool_trace || []) }}</pre></details>
        <h3>{{ $t('qaCorpus.retrieval') }}</h3><p v-if="harness && !row.retrieval.calls.length" data-testid="qa-corpus-case-retrieval-grade">{{ $t('qaCorpus.harness.noRetrievalSummary') }}</p><p v-else data-testid="qa-corpus-case-retrieval-grade">{{ $t('qaCorpus.recall') }} {{ row.retrieval.recall }} · {{ $t('qaCorpus.mrr') }} {{ row.retrieval.mrr }}</p><p>{{ $t('qaCorpus.expectedIds') }} {{ row.retrieval.expected.join(', ') }}<br />{{ $t('qaCorpus.foundIds') }} {{ row.retrieval.found.join(', ') || '—' }}</p>
        <details v-for="(call, callIndex) in row.retrieval.calls" :key="call.call_id || callIndex"><summary>{{ $t('qaCorpus.turn', { n: call.turn }) }} · {{ call.tool }} · RR {{ call.reciprocal_rank }} · k={{ call.returned_k }}</summary><p>{{ $t('qaCorpus.orderedIds') }} {{ call.article_ids.join(' → ') || '—' }}</p><pre>{{ formatted(call.arguments) }}</pre></details>
        <h3>{{ $t('qaCorpus.finalSourceCoverage') }}</h3><p>{{ row.final_source_coverage.recall }} · {{ row.final_source_coverage.found.join(', ') || '—' }}</p><p>{{ $t('qaCorpus.finalSourceLimit') }}</p>
        <div v-if="caseReview(row)" class="qa-corpus-case-review"><h3>{{ $t('qaCorpus.semantic') }}</h3><p v-if="caseReview(row).assessment_status === 'not_assessable'">{{ $t('qaCorpus.harness.notAssessable') }}</p><dl v-else><div v-for="dimension in dimensions" :key="dimension"><dt>{{ $t('qaSemanticReview.dimensions.' + dimension) }}</dt><dd>{{ caseReview(row).scores[dimension] ? 'PASS' : 'FAIL' }}</dd></div></dl><p>{{ caseReview(row).reason }}</p></div><p v-else>{{ $t('qaCorpus.pending') }}</p><p v-if="row.error" class="qa-error">{{ row.error }}</p><details><summary>{{ $t('qaCorpus.rowHash') }}</summary><code>{{ row.row_sha }}</code></details>
      </details>
    </section>
    <section v-if="capabilities?.recent.length" class="qa-corpus-history"><h2>{{ $t('qaWorkbench.history.title') }}</h2><button v-for="entry in capabilities.recent" :key="entry.id" type="button" class="qa-text-link" :disabled="loading || (active && job.id !== entry.id)" @click="showJob(entry.id)">{{ timestamp(entry.started_at) }} · {{ entry.bank.version }} · {{ $t('qaCorpus.status.' + entry.status) }}</button></section>
  </section>
</template>

<script setup>
import { qaChallenge } from '../lib/runtime.js';
import { qaDownloadPrefix } from '../lib/runtime.js';
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useI18n } from "vue-i18n";
import { AGENT, TS_SITEKEY } from "../lib/runtime.js";
import { apiFetch } from "../lib/qaSession.js";
import { createCfToken } from "../lib/cfToken.js";
import { corpusActive, corpusAnswerEvidence, corpusCasePassed, corpusCaseReview, corpusCombinedBudget, corpusCostObservation, corpusHarness, corpusLedger, corpusReview, validCorpusCapabilities, validCorpusJob } from "../lib/qaCorpusEvaluation.js";
import QaIcon from "./QaIcon.vue";
const emit = defineEmits(["phase-change", "observation-change"]);
const { t, te, locale } = useI18n();
const capabilities = ref(null), job = ref(null), loading = ref(false), cancelling = ref(false), downloading = ref(false), error = ref("");
const settings = ref(true), budget = ref(1), split = ref("all"), acknowledged = ref(false), downloadLink = ref(null), tsBox = ref(null), tsSitekey = TS_SITEKEY;
const dimensions = ["intent", "grounding", "completeness", "language"], coverageKinds = ["categories", "sources", "splits"];
const controller = new AbortController(), cfToken = createCfToken({ enabled: !!TS_SITEKEY });
let timer, revision = 0, initialized = false, widget = null, failures = 0;
const base = AGENT + "/qa/corpus-evaluations", active = computed(() => corpusActive(job.value));
const bank = computed(() => !settings.value && job.value ? job.value.bank : capabilities.value?.bank || job.value?.bank);
const review = computed(() => corpusReview(job.value)), caseReview = (row) => corpusCaseReview(job.value, row);
const harness = computed(() => corpusHarness(job.value)), ledger = computed(() => corpusLedger(job.value));
const combinedBudget = computed(() => corpusCombinedBudget(job.value));
const combinedFields = computed(() => combinedBudget.value?.version === 2 ? ["originalCap", "priorCommitted", "priorUnknown", "totalAllocationAll", "remaining"] : ["originalCap", "priorRetained", "totalAllocation", "remaining"]);
const costObservation = computed(() => corpusCostObservation(job.value));
const noRetrieval = computed(() => harness.value && job.value.cases.length > 0 && job.value.cases.every((row) => !row.retrieval.calls.length));
const notRunCaseIds = computed(() => (job.value?.selected_case_ids || []).filter((id) => !(job.value?.cases || []).some((row) => row.case_id === id)));
const missingTurns = (row) => row.questions.map((_, index) => index + 1).filter((turn) => !row.answers.some((answer) => answer.turn === turn));
const completedAnswers = computed(() => (job.value?.cases || []).reduce((sum, row) => sum + row.answers.filter((answer) => answer.status === "completed" && answer.answer_md?.trim()).length, 0));
const reviewLabel = computed(() => {
  if (!review.value) return t("qaCorpus.pending");
  if (harness.value && review.value.reviewer_kind === "ai") {
    if (review.value.passed + review.value.failed === 0) return t("qaCorpus.harness.reviewNotAssessable", { n: review.value.not_assessable });
    return t(review.value.not_assessable === 0 && review.value.passed + review.value.failed === job.value.total_cases
      ? "qaCorpus.harness.reviewSemanticCompleted" : "qaCorpus.harness.reviewCompleted",
    { observed: review.value.reviewed_cases, assessed: review.value.passed + review.value.failed, total: job.value.total_cases });
  }
  return t(review.value.reviewer_kind === "ai" ? "qaSemanticReview.completedAi" : "qaSemanticReview.completedHuman");
});
const ledgerFields = [{ key: "costCap", value: "cap" }, { key: "costCommitted", value: "committed" }, { key: "costUnknown", value: "unknown" }, { key: "costInflight", value: "inflight" }, { key: "costAvailable", value: "available" }];
const canReview = computed(() => !harness.value && !loading.value && !active.value && !capabilities.value?.busy && job.value?.report_available && job.value.completed_cases > 0);
const budgetValid = computed(() => typeof budget.value === "number" && Number.isFinite(budget.value) && budget.value >= Math.max(0.01, capabilities.value?.pricing?.per_case_reserved_estimated_usd || 0) && budget.value <= Math.min(50, capabilities.value?.limits?.max_budget_usd || 0));
const cannotStart = computed(() => harness.value || loading.value || active.value || !capabilities.value?.available || capabilities.value.busy || !budgetValid.value || !acknowledged.value || (capabilities.value.turnstile_required && !TS_SITEKEY));
const unavailable = computed(() => harness.value ? t("qaCorpus.harness.readOnly") : t("qaCorpus." + (["bank_missing", "bank_invalid"].includes(capabilities.value?.reason) ? capabilities.value.reason : "unavailable")));
const formatted = (value) => JSON.stringify(value, null, 2);
const taskTypeLabel = (value) => te("qaCorpus.taskTypes." + value) ? t("qaCorpus.taskTypes." + value) : value;
const splitLabel = (value) => te("qaCorpus.splits." + value) ? t("qaCorpus.splits." + value) : value;
const describeCoverage = (value, kind) => Object.entries(value || {}).map(([key, n]) => (kind === "task_types" ? taskTypeLabel(key) : kind === "splits" ? splitLabel(key) : key) + " " + n).join(" · ") || "—";
